<?php
$f = report_filters($_GET + ['from' => jdate(date('Y-m-d', strtotime('-30 day')), false, false)]); echo ui_date_filter('feedback', $f);
$rs = rows("SELECT f.*, s.number, c.name, c.mobile FROM feedback f JOIN sales s ON s.id=f.sale_id LEFT JOIN customers c ON c.id=f.customer_id WHERE f.created_at BETWEEN ? AND ? ORDER BY f.id DESC", [$f['from'] . ' 00:00:00', $f['to'] . ' 23:59:59']);
$ans = array_filter($rs, fn($r) => $r['rating']); $avg = $ans ? array_sum(array_column($ans, 'rating')) / count($ans) : 0;
echo '<div class="stats"><div class="stat"><span>میانگینِ امتیاز</span><b>' . fa_num(number_format($avg, 1)) . ' از ۵</b></div>' . ui_stat('فرستاده', count($rs), false) . ui_stat('پاسخ داده', count($ans), false) . ui_stat('ناراضی (۱–۲)', count(array_filter($ans, fn($r) => $r['rating'] <= 2)), false) . '</div>';
echo ui_card('نظرِ مشتریان', ui_table(['created_at' => ['زمان', 'datetime'], 'number' => ['فروش', fn($r) => '<a href="' . h(page_url('sale', ['id' => $r['sale_id']])) . '">' . h(fa_num($r['number'])) . '</a>'], 'name' => ['مشتری', fn($r) => h((string)$r['name']) . ' <small>' . h(fa_num((string)$r['mobile'])) . '</small>'],
    'rating' => ['امتیاز', fn($r) => $r['rating'] ? '<span style="color:' . ($r['rating'] <= 2 ? '#dc2626' : '#d97706') . '">' . str_repeat('★', (int)$r['rating']) . '</span>' : ui_badge('بی‌پاسخ')], 'comment' => 'نظر',
    'a' => ['', fn($r) => $r['rating'] && $r['rating'] <= 2 && !$r['followed'] ? ui_btn_api('پیگیری شد', 'fb_follow', ['id' => $r['id']], ['class' => 'sm']) : ($r['followed'] ? ui_badge('پیگیری‌شده', 'ok') : '')]], $rs, ['empty' => '—']));
if (can('settings.edit')) echo ui_card('ارسالِ خودکار', ui_form('settings_save', ['feedback_after_hours' => ['چند ساعت پس از خرید، لینکِ نظرسنجی پیامک شود (۰ = فقط دستی)', 'int']], ['feedback_after_hours' => setting('feedback_after_hours', '0')]) . '<p class="muted">قالبِ پیامکِ «نظرسنجیِ پس از خرید» باید در تنظیماتِ پیامک تعریف شود. امتیازِ ۱ و ۲ به مدیران هشدار می‌دهد.</p>');
